 export const authenticate = async (req: Request, res: Response, next: NextFunction) => {
   const authHeader = req.headers.authorization;
   if (!authHeader?.startsWith('Bearer ')) {
     return res.status(401).json({ error: 'Token n├úo fornecido' });
   }
 
   let payload: any;
   try {
     payload = jwt.verify(authHeader.split(' ')[1], JWT_SECRET);
   } catch {
     return res.status(401).json({ error: 'Token inv├ílido' });
   }
 
   try {
     const user = await prisma.user.findUnique({ where: { id: payload.sub } });
     if (!user) {
       return res.status(401).json({ error: 'Token inv├ílido' });
     }
 
     if (!user.active) {
       return res.status(403).json({ error: 'Conta n├úo ativada. Verifique seu email ou reenvie o link de ativa├º├úo.' });
     }
 
     const memberships = await prisma.membership.findMany({
       where: { userId: user.id, active: true },
       orderBy: { createdAt: 'asc' },
       include: { tenant: { include: { subscription: true } } },
     });
 
     if (memberships.length === 0) {
       return res.status(403).json({ error: 'Sem v├¡nculo com nenhuma cl├¡nica. Fale com o administrador.' });
     }
 
     const headerTenantId = String(req.headers['x-tenant-id'] || '');
     let membership = headerTenantId
       ? memberships.find((m) => m.tenantId === headerTenantId)
       : memberships.find((m) => m.tenant.status !== 'BLOQUEADO');
 
     if (!membership) {
       return res.status(403).json({ error: 'Assinatura da cl├¡nica vencida ou bloqueada. Entre em contato com o suporte.' });
     }
 
     await enforceTenantStatus(membership.tenant);
 
     if (membership.tenant.status === 'BLOQUEADO') {
       return res.status(403).json({ error: 'Assinatura da cl├¡nica vencida ou bloqueada. Entre em contato com o suporte.' });
     }
 
     req.user = {
       id: user.id,
       name: user.name,
       email: user.email,
       role: membership.role,
       tenantId: membership.tenantId,
       tenantRole: membership.role,
       tenant: {
