     { route: '/guardian', label: 'In├¡cio', icon: 'home' },
     { route: '/guardian/evolutions', label: 'Evolu├º├Áes', icon: 'trending_up' },
     { route: '/guardian/appointments', label: 'Agendamentos', icon: 'event' },
