 export class VerifyAccountComponent {
   private auth = inject(AuthService);
   private router = inject(Router);
   private route = inject(ActivatedRoute);
 
   email = '';
   code = '';
   loading = signal(false);
   error = signal('');
   success = signal('');
   emailError = signal('');
   codeError = signal('');
 
   status = signal('Verifique seu email e insira o c├│digo recebido');
 
   ngOnInit() {
     const token = this.route.snapshot.queryParamMap.get('token');
     this.email = this.route.snapshot.queryParamMap.get('email') || '';
     if (token) {
       this.verifyWithToken(token);
     }
   }
 
   verifyWithToken(token: string) {
     this.loading.set(true);
     this.status.set('Ativando sua conta...');
     fetch(`${environment.apiUrl}/auth/verify-account`, {
       method: 'POST',
       headers: { 'Content-Type': 'application/json' },
       body: JSON.stringify({ token }),
     })
       .then(res => res.json().then((d: any) => ({ ok: res.ok, d })))
       .then(({ ok, d }) => {
         if (!ok) throw new Error(d.error || 'Link inv├ílido ou j├í utilizado');
         this.onSuccess(d);
       })
       .catch(err => {
         this.error.set(err.message || 'Erro ao ativar conta');
         this.status.set('V├¡nculo inv├ílido ÔÇö digite o c├│digo manualmente');
         this.loading.set(false);
       });
   }
 
   submitCode() {
     this.emailError.set('');
     this.codeError.set('');
 
     if (!this.email) {
       this.emailError.set('Email ├® obrigat├│rio');
       return;
     }
     if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(this.email)) {
       this.emailError.set('Email inv├ílido');
       return;
     }
     if (!this.code || this.code.length !== 6) {
       this.codeError.set('Digite o c├│digo de 6 d├¡gitos');
       return;
     }
 
     this.loading.set(true);
     this.error.set('');
     fetch(`${environment.apiUrl}/auth/verify-account`, {
       method: 'POST',
       headers: { 'Content-Type': 'application/json' },
       body: JSON.stringify({ email: this.email, code: this.code }),
     })
       .then(res => res.json().then((d: any) => ({ ok: res.ok, d })))
       .then(({ ok, d }) => {
         if (!ok) throw new Error(d.error || 'Erro ao ativar conta');
         this.onSuccess(d);
       })
       .catch(err => {
         this.error.set(err.message || 'Erro ao conectar com o servidor');
         this.loading.set(false);
       });
   }
 
   onSuccess(d: any) {
     this.success.set('Conta ativada com sucesso!');
     this.status.set('Bem-vindo ao EduPsych Pro');
     this.loading.set(false);
     if (d.token && d.user) {
       this.auth.login(d.token, d.user);
     }
   }
 
   goApp() {
     if (this.auth.isLoggedIn()) {
       const user = this.auth.user();
       this.router.navigate([user?.role === 'RESPONSAVEL' ? '/guardian' : '/app/dashboard']);
     } else {
       this.router.navigate(['/login']);
     }
   }
 
   goLogin() {
     this.router.navigate(['/login']);
   }
 }
