           const key = d.toLocaleString('pt-BR', { month: 'short' }).replace('.', '').toUpperCase();
           if (months[key]) {
             const val = parseFloat(t.valor) || 0;
             if (t.tipo === 'RECEITA' || t.type === 'RECEITA') {
               months[key].receita += val;
