 export class EscolaFormComponent implements OnInit {
   private service = inject(EscolasService);
   private router = inject(Router);
   private route = inject(ActivatedRoute);
   private toast = inject(ToastService);
 
   isEdit = false;
   id = '';
   saving = signal(false);
 
   levelOptions = [
     { value: 'EDUCACAO_INFANTIL', label: 'Educa├º├úo Infantil' },
     { value: 'ANOS_INICIAIS', label: 'Anos Iniciais (1┬║ ao 5┬║)' },
     { value: 'ANOS_FINAIS', label: 'Anos Finais (6┬║ ao 9┬║)' },
     { value: 'ENSINO_MEDIO', label: 'Ensino M├®dio' },
     { value: 'SUPERIOR', label: 'Superior' },
     { value: 'PROFISSIONALIZANTE', label: 'Profissionalizante' },
   ];
 
   form: any = {
     name: '',
     levels: [],
     status: 'Ativa',
     phone: '',
     phoneIsWhatsApp: false,
     contactEmail: '',
     notes: '',
     address: {
       cep: '',
       street: '',
       neighborhood: '',
       number: '',
       complement: '',
       city: '',
       state: ''
     }
   };
 
   ngOnInit() {
     this.id = this.route.snapshot.params['id'] || '';
     this.isEdit = !!this.id;
 
     if (this.isEdit) {
       this.service.get(this.id).subscribe((res: any) => {
         let levels: string[] = [];
         if (res.levels) {
           try {
             levels = JSON.parse(res.levels);
           } catch {
             levels = res.levels ? [res.levels] : [];
           }
         }
         this.form = {
           ...this.form,
           ...res,
           levels,
           phone: res.phone || '',
           contactName: res.contactName || '',
           contactEmail: res.contactEmail || '',
           status: res.status || 'Ativa',
           address: {
             cep: res.cep || '',
             street: res.street || '',
             number: res.number || '',
             complement: res.complement || '',
             neighborhood: res.neighborhood || '',
             city: res.city || '',
             state: res.state || '',
           }
         };
       });
     }
   }
 
   isLevelSelected(level: string): boolean {
     return this.form.levels.includes(level);
   }
 
   toggleLevel(level: string) {
     const index = this.form.levels.indexOf(level);
     if (index === -1) {
       this.form.levels.push(level);
     } else {
       this.form.levels.splice(index, 1);
     }
   }
 
   onAddressChange(address: Address) {
     this.form.address = address;
   }
 
   onPhoneChange(phone: PhoneNumber) {
     this.form.phone = phone.number;
     this.form.phoneIsWhatsApp = phone.isWhatsApp;
   }
 
   save() {
     if (!this.form.name) return;
     this.saving.set(true);
 
     const data: any = {
       name: this.form.name,
       levels: JSON.stringify(this.form.levels),
       status: this.form.status,
       contactEmail: this.form.contactEmail,
       contactName: this.form.contactName,
       phone: this.form.phone,
       cep: this.form.address?.cep || '',
       street: this.form.address?.street || '',
       number: this.form.address?.number || '',
       complement: this.form.address?.complement || '',
       neighborhood: this.form.address?.neighborhood || '',
       city: this.form.address?.city || '',
       state: this.form.address?.state || '',
     };
     if (this.isEdit) data.id = this.id;
 
     const obs = this.isEdit ? this.service.update(this.id, data) : this.service.create(data);
     obs.subscribe({
       next: () => {
         this.toast.success(this.isEdit ? 'Escola atualizada com sucesso' : 'Escola criada com sucesso');
         this.router.navigate(['/app/escolas']);
       },
       error: () => {
         this.saving.set(false);
         this.toast.error('Erro ao salvar escola');
       }
     });
   }
 }

