 export class PublicFormComponent implements OnInit {
   private route = inject(ActivatedRoute);
 
   form = signal<any>(null);
   answers: Record<string, any> = {};
   loading = signal(true);
   sending = signal(false);
   submitted = signal(false);
   error = signal('');
   formError = signal('');
 
   private token = '';
 
   ngOnInit() {
     this.token = this.route.snapshot.paramMap.get('token') || '';
     fetch(`${environment.apiUrl}/document-requests/public/${this.token}`)
       .then(res => res.json().then((d: any) => ({ ok: res.ok, d })))
       .then(({ ok, d }) => {
         if (!ok) throw new Error(d.error || 'Formul├írio n├úo encontrado');
         this.form.set(d);
         this.loading.set(false);
       })
       .catch(err => {
         this.error.set(err.message || 'Formul├írio indispon├¡vel');
         this.loading.set(false);
       });
   }
 
   submit() {
     this.formError.set('');
     const required = (this.form()?.fields || []).filter((f: any) => f.required);
     for (const f of required) {
       const v = this.answers[f.id];
       if (v === undefined || v === '' || v === null) {
         this.formError.set(`Preencha o campo obrigat├│rio: ${f.label}`);
         return;
       }
     }
 
     this.sending.set(true);
     fetch(`${environment.apiUrl}/document-requests/public/${this.token}/submit`, {
       method: 'POST',
       headers: { 'Content-Type': 'application/json' },
       body: JSON.stringify({ answers: this.answers }),
     })
       .then(res => res.json().then((d: any) => ({ ok: res.ok, d })))
       .then(({ ok, d }) => {
         if (!ok) throw new Error(d.error || 'Erro ao enviar');
         this.sending.set(false);
         this.submitted.set(true);
       })
       .catch(err => {
         this.formError.set(err.message || 'Erro ao enviar formul├írio');
         this.sending.set(false);
       });
   }
 }
