         this.loadEvolutions(patientId);
       }
     });
   }
 
   loadEvolutions(patientId: string) {
     this.guardianService.getEvolutions(patientId).subscribe({
       next: (res: any) => {
         const data = res.data || [];
         this.records.set(data);
         this.filteredRecords.set(data);
       }
     });
   }
 
   applyFilters() {
     let filtered = this.records();
