     html += `<div style="background: #f0fdfa; padding: 20px; border-radius: 12px; margin-bottom: 20px;">
       <h3 style="color: #007F80; margin: 0 0 10px;">Plano Geral</h3>
-      <p><strong>Dura├º├úo:</strong> ${p.overallPlan.totalEstimatedWeeks} semanas | <strong>Frequ├¬ncia:</strong> ${p.overallPlan.sessionFrequency} | <strong>Reavalia├º├úo:</strong> ${p.overallPlan.reassessmentPeriod}</p>
+      <p><strong>Dura├º├úo:</strong> ${p.overallPlan.totalEstimatedWeeks} semanas | <strong>Frequ├¬ncia:</strong> ${escapeHtml(p.overallPlan.sessionFrequency)} | <strong>Reavalia├º├úo:</strong> ${escapeHtml(p.overallPlan.reassessmentPeriod)}</p>
