               <tr><td style="padding: 8px 0; color: #666;">Pontua├º├úo Geral:</td><td style="padding: 8px 0; font-weight: bold; font-size: 18px; color: #007F80;">${data.totalScore}/${data.totalMax} (${data.overallPercentage}%)</td></tr>
               <tr><td style="padding: 8px 0; color: #666;">Classifica├º├úo:</td><td style="padding: 8px 0; font-weight: bold;">${this.getClassification(protocolo.averageScore)}</td></tr>
             </table>
             <h3 style="color: #007F80; font-size: 16px; margin: 30px 0 15px; border-bottom: 2px solid #007F80; padding-bottom: 8px;">Resultado por Categoria</h3>
