     { key: 'RESPONDIDO', label: 'Respondidas' },
     { key: 'EXPIRADO', label: 'Expiradas' },
   ];
 
   ngOnInit() { this.load(); }
 
   badgeCls(status: string) {
     return STATUS[status]?.cls || STATUS['PENDENTE'].cls;
