import { Component, inject, signal, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { ApiService } from '@core/services/api.service';
import { ToastService } from '@shared/components/toast.component';

@Component({
  selector: 'app-prontuario',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  template: `
    <div class="page">
      <div class="header">
        <div><h1>Prontu├írio</h1><p class="subtitle">Registro de evolu├º├úo do paciente</p></div>
        <a [routerLink]="['/app/pacientes', pacienteId]" class="btn btn-outline"><span class="material-icons">arrow_back</span></a>
      </div>
      <div class="card" style="margin-bottom:16px"><div class="card-body">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
          <h3 style="margin:0">{{ editingId() ? 'Editar Anota├º├úo' : 'Nova Anota├º├úo' }}</h3>
          @if (editingId()) {
            <button class="btn btn-outline" (click)="resetForm()"><span class="material-icons" style="font-size:16px">add</span> Nova anota├º├úo</button>
          }
        </div>
        <input class="form-control" [(ngModel)]="newEntry.titulo" placeholder="T├¡tulo" style="margin-bottom:8px">
        <textarea class="form-control" [(ngModel)]="newEntry.conteudo" rows="4" placeholder="Descreva a evolu├º├úo..." style="margin-bottom:8px"></textarea>
        <button class="btn btn-primary" (click)="saveEntry()">{{ editingId() ? 'Salvar Altera├º├úo' : 'Salvar Anota├º├úo' }}</button>
      </div></div>
      @for (entry of entries(); track entry.id) {
        <div class="card" style="margin-bottom:8px"><div class="card-body">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
            <strong>{{ entry.titulo }}</strong>
            <div style="display:flex;align-items:center;gap:4px">
              <button class="btn btn-outline" style="padding:4px 8px" title="Editar" (click)="editEntry(entry)"><span class="material-icons" style="font-size:16px">edit</span></button>
              <button class="btn btn-outline" style="padding:4px 8px;color:#DC2626;border-color:#FECACA" title="Excluir" (click)="deleteEntry(entry)"><span class="material-icons" style="font-size:16px">delete</span></button>
            </div>
          </div>
