     { id: 'nfse', label: 'NFS-e', icon: 'receipt_long', route: '/app/financeiro/nfse', count: signal(0) },
     {
       id: 'documentos', label: 'Documentos', icon: 'folder_open',
       children: [
         { id: 'doc-arquivos', label: 'Arquivos', icon: 'folder', route: '/app/documentos' },
         { id: 'doc-diario', label: 'Di├írio de Sess├Áes', icon: 'edit_note', route: '/app/documentos-clinicos/diario' },
         { id: 'doc-frequencia', label: 'Frequ├¬ncia', icon: 'checklist', route: '/app/documentos-clinicos/frequencia' },
         { id: 'doc-plano', label: 'Plano de Interven├º├úo', icon: 'assignment', route: '/app/documentos-clinicos/plano' },
         { id: 'doc-biblioteca', label: 'Biblioteca', icon: 'menu_book', route: '/app/biblioteca' },
         { id: 'doc-laudos', label: 'Laudos', icon: 'description', route: '/app/laudos' },
         { id: 'doc-solicitacoes', label: 'Solicita├º├Áes', icon: 'assignment_turned_in', route: '/app/solicitacoes' },
